# CRM comparisons use the hand-built CRM ranking in build.py (scores, G2 ratings, URLs).
CRM = {"slug": "best-crm-software", "crumb": "CRM Software", "plural": "CRMs for Sales Teams", "date": "2026-10-02",
       "_ranked": TOOLS, "_score": score,
       "tools": {t["id"]: {"name": t["name"], "short": SHORT[t["id"]], "url": URLS[t["id"]], "g2": G2[t["id"]],
                           "links": [(f"/tools/best-{t['id']}-alternatives/", f"{SHORT[t['id']]} alternatives")] if t["id"] in ("hubspot", "pipedrive") else []}
                 for t in CONSIDERED}}

